package net.civeira.phylax.features.access.userpersonalapikey.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.userpersonalapikey.application.visibility.UserPersonalApiKeyVisibilityCheck;

public class OnlySelfAccesibles {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes UserPersonalApiKeyVisibilityCheck filter) {
    Actor actor = filter.getActor();
    filter.peek(fl -> fl.setOnlySelfAccesibles(actor.getUid()));
  }
}
